mapper.select:
select v.*
from (

) v


        and v.provider_code = #{providerCode}


        and v.model_type = #{modelType}


        and (lower(v.model_name) like lower(#{keyword}) escape '\'
             or lower(v.model_code) like lower(#{keyword}) escape '\')


        and v.connection_count > 0


        and v.connection_count = 0


order by v.sort, v.id
